function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value in nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 100000000) return 'k is an integer from 1 to 10^8.';
  return null;
}

