function minimalKSum(nums, k) {
  nums.sort((a, b) => a - b);
  let limit = k;
  let total = (k * (k + 1)) / 2;
  let previous = 0;

  for (const value of nums) {
    if (value > limit) {
      break;
    }
    if (value === previous) {
      continue;
    }
    previous = value;
    limit++;
    total += limit - value;
  }
  return total;
}

brute:
function minimalKSum(nums, k) {
  const present = new Set(nums);
  let total = 0;
  let picked = 0;
  for (let candidate = 1; picked < k; candidate++) {
    if (!present.has(candidate)) {
      total += candidate;
      picked++;
    }
  }
  return total;
}

