function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    const top = pick(3, 20);
    return [Array.from({ length: n }, () => pick(1, top)), pick(1, 12)];
  }
  const k = pick(1, 100000000);
  const n = 2000;
  const nums = [];
  // Half the values land among the first numbers we would pick, so they actually shift the answer.
  for (let i = 0; i < n; i++) nums.push(rand() < 0.5 ? pick(1, Math.min(1000000000, k + n)) : pick(1, 1000000000));
  // A run of consecutive values right at the edge of the chosen range.
  const start = Math.max(1, k - 50);
  for (let i = 0; i < 100; i++) nums[pick(0, n - 1)] = Math.min(1000000000, start + i);
  return [nums, k];
}
